const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;
const errors = [];

if (!body.request_id) errors.push({ field: 'request_id', reason: 'MISSING_REQUIRED_FIELD' });
if (body.confirm_same_product_family !== true) errors.push({ field: 'confirm_same_product_family', reason: 'MUST_BE_TRUE' });
if (body.confirm_no_review_manipulation !== true) errors.push({ field: 'confirm_no_review_manipulation', reason: 'MUST_BE_TRUE' });
if (body.confirm_understands_risk !== true) errors.push({ field: 'confirm_understands_risk', reason: 'MUST_BE_TRUE' });

if (errors.length > 0) {
  return [{ json: {
    request_id: body.request_id || null,
    decision: 'APPROVAL_REJECTED',
    reason: 'MISSING_CONFIRMATIONS',
    errors: errors,
    message: 'All required confirmations must be true before approval.'
  }}];
}

return [{ json: {
  request_id: body.request_id,
  decision: 'VALID_APPROVAL_INPUT',
  confirm_same_product_family: body.confirm_same_product_family,
  confirm_no_review_manipulation: body.confirm_no_review_manipulation,
  confirm_matrix_correct: body.confirm_matrix_correct || false,
  confirm_understands_risk: body.confirm_understands_risk,
  approved_by: body.approved_by || 'seller'
}}];

const restored = $input.first().json;
const validationRaw = restored.validation_raw || {};
const approvalData = restored.approval_data || {};

if (!approvalData.request_id || approvalData.decision === 'APPROVAL_REJECTED') {
  return [{ json: approvalData || { decision: 'APPROVAL_REJECTED', reason: 'INVALID_INPUT' } }];
}

const validationRow = Array.isArray(validationRaw)
  ? (validationRaw[0] || {})
  : (validationRaw.decision ? validationRaw : {});

const decision = validationRow.decision || '';
const hardBlocks = validationRow.hard_blocks_json || [];

const isBlocked = decision === 'BLOCKED' ||
  (Array.isArray(hardBlocks) && hardBlocks.length > 0);

if (isBlocked) {
  return [{ json: {
    request_id: approvalData.request_id,
    decision: 'APPROVAL_REJECTED',
    reason: 'HARD_BLOCKS_EXIST',
    message: 'This request has hard blocks and cannot be approved.',
    validation_decision: decision
  }}];
}

if (decision !== 'CAN_CONTINUE_TO_DRY_RUN' && decision !== 'MATRIX_VALID') {
  return [{ json: {
    request_id: approvalData.request_id,
    decision: 'APPROVAL_REJECTED',
    reason: 'VALIDATION_NOT_PASSED',
    message: 'Validation not passed. Current status: ' + (decision || 'unknown'),
    validation_decision: decision
  }}];
}

return [{ json: {
  request_id: approvalData.request_id,
  decision: 'APPROVED_FOR_PAYLOAD_PREVIEW',
  message: 'All confirmations received and validation passed. Ready for payload preview.',
  confirm_same_product_family: approvalData.confirm_same_product_family,
  confirm_no_review_manipulation: approvalData.confirm_no_review_manipulation,
  confirm_matrix_correct: approvalData.confirm_matrix_correct,
  confirm_understands_risk: approvalData.confirm_understands_risk,
  approved_by: approvalData.approved_by,
  validation_decision: decision
}}];

const prev = $input.first().json;
return [{ json: {
  _original_payload: prev,
  request_id: prev.request_id,
  approval_status: prev.decision,
  approved_by: prev.approved_by || 'seller',
  confirm_same_product_family: prev.confirm_same_product_family || false,
  confirm_no_review_manipulation: prev.confirm_no_review_manipulation || false,
  confirm_matrix_correct: prev.confirm_matrix_correct || false,
  confirm_understands_risk: prev.confirm_understands_risk || false,
  notes: prev.message || null
}}];

const validationRaw = $input.first().json;
const approvalData = $('Approval Input Validator').first().json;

return [{ json: {
  validation_raw: validationRaw,
  approval_data: approvalData
}}];
